  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.05rem;
}
.brand-mark {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--primary), #9c7aff);
  box-shadow: 0 6px 18px rgba(91, 61, 245, 0.35);
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 20px;
  font-size: 0.95rem;
