.btn-primary {
  background: linear-gradient(135deg, var(--primary), var(--primary-2));
  color: #fff;
  box-shadow: 0 10px 20px rgba(91, 61, 245, 0.25);
}
.btn-primary:hover { transform: translateY(-1px); filter: brightness(1.05); }
.btn-ghost {
  border: 1px solid var(--border);
  background: #fff;
  color: #2c3252;
}
.btn-ghost:hover { border-color: #cfd2ea; }

.hero {
  padding: 80px 0 64px;
  background: radial-gradient(circle at top right, rgba(125, 91, 255, 0.18), transparent 46%), #fff;
