.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 42px;
  align-items: center;
}
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-mock {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  padding: 22px;
}
.mock-top { display: flex; justify-content: space-between; margin-bottom: 16px; }
.pill { font-size: 12px; font-weight: 700; color: #4a4f6f; background: #f1f2fc; padding: 6px 10px; border-radius: 999px; }
.video-box {
  border-radius: 14px;
  background: linear-gradient(145deg, #5b3df5, #8c73ff);
  height: 230px;
  position: relative;
}
.video-box::before {
  content: "▶";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  color: #fff;
  font-size: 2rem;
}

.grid-3, .grid-4 {
  display: grid;
  gap: 18px;
}
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 6px 18px rgba(34, 34, 79, 0.06);
  padding: 20px;
}
.icon-dot {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  margin-bottom: 12px;
  background: linear-gradient(145deg, #6b4aff, #9f86ff);
