.toggle-wrap {
  display: inline-flex;
  background: #edf0ff;
  border-radius: 999px;
  padding: 4px;
}
.toggle-wrap button {
  border: 0;
  background: transparent;
  padding: 8px 14px;
  border-radius: 999px;
  font-weight: 700;
  cursor: pointer;
}
.toggle-wrap button.active {
