  color: #2d1c8d;
  box-shadow: 0 4px 10px rgba(38, 29, 119, 0.18);
}
.save-badge { font-size: 12px; color: #fff; background: #16a34a; padding: 4px 10px; border-radius: 999px; }

.slider-box {
