.expand-content { display: none; margin-top: 10px; padding-top: 10px; border-top: 1px dashed #d9ddf8; }
.expand-content.open { display: block; }

.comparison-table { width: 100%; border-collapse: collapse; background: #fff; border: 1px solid var(--border); border-radius: 14px; overflow: hidden; }
.comparison-table th, .comparison-table td { padding: 12px; border-bottom: 1px solid #edf0ff; text-align: left; font-size: 0.93rem; }
.comparison-table th { background: #f7f8ff; color: #262b49; }

.faq-item { border: 1px solid var(--border); border-radius: 12px; margin-bottom: 10px; overflow: hidden; background: #fff; }
