.faq-a.open { display: block; }

.auth-wrap { min-height: calc(100vh - 76px); display: grid; place-items: center; padding: 40px 0; background: radial-gradient(circle at top right, rgba(125, 91, 255, 0.14), transparent 50%), #f9faff; }
